PRAGMA foreign_keys = ON;

-- Calendar days.
CREATE TABLE "day" (
  "at" TEXT NOT NULL PRIMARY KEY DEFAULT '2000-02-29' CHECK ("at" IS NULL OR (typeof("at") = 'text' AND length("at") = 10 AND instr("at", char(0)) = 0 AND "at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("at", 1, 4) BETWEEN '0001' AND '9999' AND substr("at", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("at", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("at", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("at", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("at", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("at", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)),
  "optional" TEXT DEFAULT NULL CHECK ("optional" IS NULL OR (typeof("optional") = 'text' AND length("optional") = 10 AND instr("optional", char(0)) = 0 AND "optional" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("optional", 1, 4) BETWEEN '0001' AND '9999' AND substr("optional", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("optional", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("optional", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("optional", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("optional", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("optional", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)),
  "raw" TEXT NOT NULL DEFAULT ('0001-01-01') CHECK ("raw" IS NULL OR (typeof("raw") = 'text' AND length("raw") = 10 AND instr("raw", char(0)) = 0 AND "raw" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("raw", 1, 4) BETWEEN '0001' AND '9999' AND substr("raw", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("raw", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("raw", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("raw", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("raw", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("raw", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END))
) STRICT;

CREATE TABLE "range" (
  "start" TEXT NOT NULL CHECK ("start" IS NULL OR (typeof("start") = 'text' AND length("start") = 10 AND instr("start", char(0)) = 0 AND "start" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("start", 1, 4) BETWEEN '0001' AND '9999' AND substr("start", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("start", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("start", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("start", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("start", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("start", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)) CHECK (("start" >= '0001-01-01')),
  "finish" TEXT CHECK ("finish" IS NULL OR (typeof("finish") = 'text' AND length("finish") = 10 AND instr("finish", char(0)) = 0 AND "finish" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("finish", 1, 4) BETWEEN '0001' AND '9999' AND substr("finish", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("finish", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("finish", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("finish", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("finish", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("finish", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)),
  CHECK ((("finish" IS NULL) OR ("finish" >= "start")))
) STRICT;

CREATE TABLE "ref" (
  "day" TEXT NOT NULL DEFAULT '2000-02-29' CHECK ("day" IS NULL OR (typeof("day") = 'text' AND length("day") = 10 AND instr("day", char(0)) = 0 AND "day" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("day", 1, 4) BETWEEN '0001' AND '9999' AND substr("day", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("day", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("day", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("day", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("day", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("day", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)) REFERENCES "day"("at") ON DELETE RESTRICT
) STRICT;

CREATE TABLE "pair" (
  "start" TEXT NOT NULL CHECK ("start" IS NULL OR (typeof("start") = 'text' AND length("start") = 10 AND instr("start", char(0)) = 0 AND "start" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("start", 1, 4) BETWEEN '0001' AND '9999' AND substr("start", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("start", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("start", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("start", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("start", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("start", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)),
  "finish" TEXT NOT NULL CHECK ("finish" IS NULL OR (typeof("finish") = 'text' AND length("finish") = 10 AND instr("finish", char(0)) = 0 AND "finish" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr("finish", 1, 4) BETWEEN '0001' AND '9999' AND substr("finish", 6, 2) BETWEEN '01' AND '12' AND CAST(substr("finish", 9, 2) AS INTEGER) BETWEEN 1 AND CASE CAST(substr("finish", 6, 2) AS INTEGER) WHEN 2 THEN 28 + (CAST(substr("finish", 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr("finish", 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr("finish", 1, 4) AS INTEGER) % 400 = 0)) WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END)),
  PRIMARY KEY ("start", "finish")
) STRICT;

CREATE INDEX "ref_day_idx" ON "ref" ("day");
